reference_solution:
def check_inclusion(s1, s2):
    s = s2
    t = s1
    m, n = len(t), len(s)
    if m > n:
        return False
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    window = {}
    left = 0
    matches = 0
    required = len(need)
    for right in range(n):
        ch = s[right]
        window[ch] = window.get(ch, 0) + 1
        if ch in need and window[ch] == need[ch]:
            matches += 1
        if right - left + 1 > m:
            left_ch = s[left]
            if left_ch in need and window[left_ch] == need[left_ch]:
                matches -= 1
            window[left_ch] -= 1
            left += 1
        if matches == required:
            return True
    return False
